136	      });
137	
138	      expect(received).toHaveLength(1);
139	      expect(received[0]).toMatchObject({
140	        issueId: issue.id,
141	        previousAssigneeId: null,
142	        assigneeId: tenant.userIds.member,
143	      });
144	    } finally {
145	      off();
146	    }
147	  });
148	
149	  it("archives rather than deletes, emitting issue.archived", async () => {
150	    const issue = await issueService.createIssue(
151	      tenant.actors.member,
152	      issueInput(tenant.org.id, tenant.project.id, { title: "Archive target" }),
153	    );
154	
155	    const received: unknown[] = [];
156	    const off = subscribe("issue.archived", (payload) => {
157	      received.push(payload);
158	    });
159	
160	    try {
161	      const archived = await issueService.archiveIssue(
162	        tenant.actors.member,
163	        tenant.org.id,
164	        issue.id,
165	      );
166	
167	      expect(archived.archivedAt).not.toBeNull();
168	
169	      // Still reachable by id: archiving patches the row rather than deleting it.
170	      const stillThere = await issueRepo.findIssueById(tenant.org.id, issue.id);
171	      expect(stillThere).not.toBeNull();
172	      expect(stillThere?.archivedAt).not.toBeNull();
173	
174	      expect(received).toHaveLength(1);
175	      expect(received[0]).toMatchObject({ issueId: issue.id, projectId: issue.projectId });
176	    } finally {
177	      off();
178	    }
179	  });
180	});

