          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id, projectId: issues.projectId })
    .all();

  return rows.map((row) => ({
    issueId: row.id as IssueId,
    projectId: row.projectId as ProjectId,
  }));
}

